import math

# Reusing the functions from before
def calculate_p(epsilon):
    discriminant = 3 + 3*epsilon + epsilon**2
    if discriminant < 0:
        return None
    sqrt_d = math.sqrt(discriminant)
    p = (4 + 2*epsilon + sqrt_d) / 2
    return p

def calculate_E(epsilon):
    p = calculate_p(epsilon)
    if p is None:
        return float('inf')

    # p=s, r=1, q=1+epsilon
    q = 1 + epsilon

    # We must ensure q > 0
    if q <= 0:
        return float('inf')

    term1 = p / q
    term2 = q / p
    E = 2 * (term1 + term2)
    return E

# Test larger negative values of epsilon
epsilons_large = [-0.2, -0.5, -0.8, -0.9]

results_large = {}
for e in epsilons_large:
    E = calculate_E(e)
    results_large[e] = E

print("E values for larger negative perturbations (p=s, r=1, q=1+epsilon):")
for e, E in results_large.items():
    print(f"epsilon={e:.3f}, E={E}")
